      draw((-1,i)--(6,i));
      }
[/asy]

*Proof.* Color some squares blue or red as follows:

  [asy]
      size(4cm);
      path sq = (0,0)--(0,1)--(1,1)--(1,0)--cycle;
      for (int i=-1;i<5;++i) {
